/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

input.new_string:
/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

/**
 * Loads a row the change may point at.
 *
 * A hit inside the workspace is returned. A hit that belongs to another
 * workspace is refused with `assertOrgScope` — the same error as any other
 * cross-workspace access. Anything else is not found, so a missing id is not
 * reported as a tenant violation.
 */
export async function requireScoped<T extends TenantScoped>(
  actor: Actor,
  entity: string,
  id: string,
  findScoped: () => Promise<T | null>,
  findAny: () => Promise<T | null>,
): Promise<T> {
  const scoped = await findScoped();
  if (scoped) return scoped;

  const anywhere = await findAny();
  if (anywhere) assertOrgScope(actor, anywhere.orgId);
  throw new NotFoundError(entity, id);
}

