function requireProject(actor: Actor, orgId: OrgId, projectId: ProjectId) {
  return requireScoped(
    actor,
    "Project",
    projectId,
    () => projectRepo.findProjectById(orgId, projectId),
    () => projectRepo.findProjectByIdAny(projectId),
  );
}

function requireIssue(actor: Actor, orgId: OrgId, issueId: IssueId) {
  return requireScoped(
    actor,
    "Issue",
    issueId,
    () => issueRepo.findIssueById(orgId, issueId),
    () => issueRepo.findIssueByIdAny(issueId),
  );
}

async function assertAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<void> {
  if (assigneeId === null) return;
  await assertCurrentMember(orgId, assigneeId);
}

/**
 * Parent, assignee and labels are checked before any row is written. A parent
 * must be a live issue of the same project. Another workspace is a tenant
 * violation; a missing, archived, or cross-project parent is not found.
 */
async function assertIssueReferences(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  input: {
    assigneeId: UserId | null;
    parentId: IssueId | null;
    labelIds: readonly LabelId[];
  },
): Promise<void> {
  await assertAssignee(orgId, input.assigneeId);

  if (input.parentId !== null) {
    const parent = await requireIssue(actor, orgId, input.parentId);
    if (isArchived(parent) || parent.projectId !== projectId) {
      throw new NotFoundError("Issue", input.parentId);
    }
  }

  await assertLabels(actor, orgId, input.labelIds);
}

async function assertLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  for (const labelId of labelIds) {
    await requireScoped(
      actor,
      "Label",
      labelId,
      () => labelRepo.findLabelById(orgId, labelId),
      () => labelRepo.findLabelByIdAny(labelId),
    );
  }
}

