/**
 * A reply must target a live top-level comment on the same issue. Another
 * workspace is a tenant violation. A missing comment, a deleted one, one on
 * another issue, or a reply-to-a-reply is not found — and nothing is posted.
 */
async function assertReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await requireComment(actor, orgId, parentId);
  if (isArchived(parent) || parent.issueId !== issueId || parent.parentId !== null) {
    throw new NotFoundError("Comment", parentId);
  }
}

/**
 * Mentions, whether written as `@handle` or supplied by the composer, are
 * kept only when they name a current member of this workspace. Anyone else
 * is dropped: the comment still posts, and that person is never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    status: "active",
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const mentioned: UserId[] = [...resolved];
  const seen = new Set<UserId>(resolved);

  for (const userId of clientProvided) {
    if (seen.has(userId)) continue;
    const member = await memberRepo.findMember(orgId, userId);
    if (!member || member.status !== "active") continue;
    seen.add(userId);
    mentioned.push(userId);
  }

  return mentioned;
}

