import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { NotFoundError } from "@/lib/errors";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let home: Tenant;
let other: Tenant;
let homeIssue: Issue;
let otherIssue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  home = await createTenant("home");
  other = await createTenant("other");
  homeIssue = await issueService.createIssue(
    home.actors.member,
    issueInput(home.org.id, home.project.id, { title: "Home issue" }),
  );
  otherIssue = await issueService.createIssue(
    other.actors.member,
    issueInput(other.org.id, other.project.id, { title: "Other issue" }),
  );
});

afterAll(() => cleanup());

describe("reference guards", () => {
  it("refuses a foreign label and writes nothing", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Other project",
      color: "#111111",
      description: null,
    });
    const before = await issueRepo.countIssues(home.org.id, home.project.id);
    const events: unknown[] = [];
    const off = subscribe("issue.created", (payload) => events.push(payload));
    try {
      await expect(
        issueService.createIssue(home.actors.member, {
          ...issueInput(home.org.id, home.project.id, { title: "Labeled" }),
          labelIds: [foreign.id],
        }),
      ).rejects.toBeInstanceOf(TenantScopeError);
      expect(await issueRepo.countIssues(home.org.id, home.project.id)).toBe(before);
      expect(events).toEqual([]);
    } finally {
      off();
    }
  });

  it("refuses a missing label", async () => {
    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Missing label" }),
        labelIds: ["01HNOTEXISTLABEL0000000000" as never],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("does not change fields when a label update is refused", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Stale",
      color: "#222222",
      description: null,
    });
    const issue = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, home.project.id, { title: "Keep me" }),
    );
    await expect(
