        labelIds: ["01HNOTEXISTLABEL0000000000" as never],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("does not change fields when a label update is refused", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Stale",
      color: "#222222",
      description: null,
    });
    const issue = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, home.project.id, { title: "Keep me" }),
    );
    await expect(
      issueService.updateIssue(home.actors.member, {
        orgId: home.org.id,
        issueId: issue.id,
        title: "Changed",
        labelIds: [foreign.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    const still = await issueRepo.findIssueById(home.org.id, issue.id);
    expect(still?.title).toBe("Keep me");
    expect(still?.labelIds).toEqual([]);
  });

  it("hides a label that was attached from another workspace", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "Not ours",
      color: "#333333",
      description: null,
    });
    await labelRepo.setIssueLabels(home.org.id, homeIssue.id, [foreign.id]);
    const found = await issueService.getIssue(home.actors.member, home.org.id, homeIssue.id);
    expect(found.labels).toEqual([]);
    expect(found.issue.labelIds).toEqual([]);
  });

  it("refuses parents that are not a live issue of the same project", async () => {
    const before = await issueRepo.countIssues(home.org.id, home.project.id);
    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Cross org parent" }),
        parentId: otherIssue.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const second = await projectRepo.insertProject({
      orgId: home.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, second.id, { title: "Other project" }),
    );
    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Cross project parent" }),
        parentId: elsewhere.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await issueService.createIssue(
      home.actors.member,
      issueInput(home.org.id, home.project.id, { title: "Will archive" }),
    );
    await issueService.archiveIssue(home.actors.member, home.org.id, archived.id);
    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Archived parent" }),
        parentId: archived.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.createIssue(home.actors.member, {
        ...issueInput(home.org.id, home.project.id, { title: "Missing parent" }),
        parentId: "01HNOTEXISTISSUE00000000000" as never,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const child = await issueService.createIssue(home.actors.member, {
      ...issueInput(home.org.id, home.project.id, { title: "Good child" }),
      parentId: homeIssue.id,
    });
    expect(child.parentId).toBe(homeIssue.id);
    expect(await issueRepo.countIssues(home.org.id, home.project.id)).toBeGreaterThan(before);
  });

  it("refuses replies that cannot appear in the thread", async () => {
    const top = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      body: "top",
      parentId: null,
      mentionedUserIds: [],
