    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "cross org",
        parentId: otherTop.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await commentService.deleteComment(home.actors.member, {
