      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "on deleted",
        parentId: top.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const live = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      body: "live top",
      parentId: null,
      mentionedUserIds: [],
    });
    const reply = await commentService.createComment(home.actors.member, {
      orgId: home.org.id,
      issueId: homeIssue.id,
      body: "a reply",
      parentId: live.id,
      mentionedUserIds: [],
    });
    await expect(
      commentService.createComment(home.actors.member, {
        orgId: home.org.id,
        issueId: homeIssue.id,
        body: "reply to reply",
        parentId: reply.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await commentRepo.countComments(home.org.id, homeIssue.id)).toBe(before + 2);
